public class PrefixSum {
    public int[] buildPrefixSum(int[] arr) {
        if (arr == null) return new int[]{0};
        int[] prefix = new int[arr.length + 1];
        prefix[0] = 0; // Explicit empty prefix
        for (int i = 0; i < arr.length; i++) {
            prefix[i + 1] = prefix[i] + arr[i];
        }
        return prefix;
    }

    public int querySum(int[] prefix, int left, int right) {
        // left is inclusive, right is exclusive [left, right)
        if (left < 0 || right >= prefix.length || left > right) {
            throw new IllegalArgumentException("Invalid range boundaries");
        }
        return prefix[right] - prefix[left];
    }
}
